module benchmark/solution

export pure func isLeapYear(y: int) -> bool ! {}
ensures { result == ((y % 4 == 0 && y % 100 != 0) || y % 400 == 0) }
{
  (y % 4 == 0 && y % 100 != 0) || y % 400 == 0
}

export pure func daysInMonth(m: int, y: int) -> int ! {}
requires { m >= 1, m <= 12 }
ensures { result >= 28, result <= 31 }
{
  if m == 2 then (if isLeapYear(y) then 29 else 28)
  else if m == 4 || m == 6 || m == 9 || m == 11 then 30
  else 31
}

export func main() -> () ! {IO} {
  println(show(isLeapYear(1900)));
  println(show(isLeapYear(2000)));
  println(show(isLeapYear(2024)));
  println(show(isLeapYear(2023)));
  println(show(daysInMonth(2, 2000)));
  println(show(daysInMonth(2, 1900)));
  println(show(daysInMonth(4, 2023)))
}

